// ─── Test 12: NextUpWidget renders 3 booking cards ───────────────────────────

test('NextUpWidget renders 3 booking cards in demo mode', async ({ demoPage: page }) => {
  await gotoDashboard(page)

  const widget = page.locator('[data-testid="next-up-widget"]')
  if (!(await widget.isVisible({ timeout: 5_000 }).catch(() => false))) {
    test.skip()
    return
  }

  await expect(widget).toBeVisible()

  // Three cards total — first is accent, others are plain
  const firstCard = widget.locator('[data-testid="next-up-card-first"]')
  const otherCards = widget.locator('[data-testid="next-up-card"]')

  await expect(firstCard).toHaveCount(1)
  await expect(otherCards).toHaveCount(2)
})

// ─── Test 13: First NextUp card has accent bg and Rust border ─────────────────

test('first NextUp card has accent bg and Rust left border', async ({ demoPage: page }) => {
  await gotoDashboard(page)

  const firstCard = page.locator('[data-testid="next-up-card-first"]')
  if (!(await firstCard.isVisible({ timeout: 5_000 }).catch(() => false))) {
