    return
  }

  const cls = await firstCard.getAttribute('class') ?? ''
  expect(cls).toContain('border-l-')
  expect(cls).toContain('color-rust')
  expect(cls).toContain('color-accent')
})

// ─── Test 14: Deposit pending pill fires send reminder ────────────────────────

test('clicking deposit pending pill on NextUp card fires send reminder', async ({ demoPage: page }) => {
  await gotoDashboard(page)

  const widget = page.locator('[data-testid="next-up-widget"]')
  if (!(await widget.isVisible({ timeout: 5_000 }).catch(() => false))) {
    test.skip()
    return
  }

  // Demo booking-2 has depositPaid=false — "Deposit pending" pill should appear
  const depositPill = widget.locator('button[aria-label="Deposit pending"]').first()
  if (!(await depositPill.isVisible({ timeout: 3_000 }).catch(() => false))) {
    test.skip()
    return
  }

  await depositPill.click()
  // After click, a toast "Reminder sent." or loading state should appear
  // We assert the button becomes disabled/loading rather than requiring a toast
  await expect(depositPill).toBeDisabled({ timeout: 3_000 })
})

// ─── Test 15: Today's schedule timeline renders artist rows ──────────────────

test('schedule timeline renders artist rows in demo mode', async ({ demoPage: page }) => {
  await gotoDashboard(page)

  const timeline = page.locator('[data-testid="schedule-timeline-widget"]')
  if (!(await timeline.isVisible({ timeout: 5_000 }).catch(() => false))) {
    test.skip()
    return
