  await expect(timeline).toBeVisible()

  // Demo data has 4 artists → 4 timeline lanes
  const lanes = timeline.locator('[data-testid="timeline-lane"]')
  const count = await lanes.count()
  expect(count).toBeGreaterThanOrEqual(1)
