// ─── Test 16: NOW line is positioned within the timeline ─────────────────────

test('NOW red line is positioned within visible range in demo mode', async ({ demoPage: page }) => {
  await gotoDashboard(page)

  const timeline = page.locator('[data-testid="schedule-timeline-widget"]')
  if (!(await timeline.isVisible({ timeout: 5_000 }).catch(() => false))) {
    test.skip()
    return
  }

  const nowLine = page.locator('[data-testid="now-line"]')

  // NOW line only renders when current time is within studio hours (10:00–22:00)
  // During a CI run this may be outside those hours — gracefully skip
  const nowVisible = await nowLine.isVisible({ timeout: 3_000 }).catch(() => false)
  if (!nowVisible) {
    test.skip()
    return
  }

  const pctAttr = await nowLine.getAttribute('data-now-pct')
  expect(pctAttr).toBeTruthy()
  const pct = Number(pctAttr)
  // Must be between 0 and 100 inclusive
  expect(pct).toBeGreaterThanOrEqual(0)
  expect(pct).toBeLessThanOrEqual(100)
})

