    return
  }

  await page.mouse.click(box.x + box.width * 0.5, box.y + box.height * 0.5)

  await expect(page).toHaveURL(
    new RegExp(`appointments/new.*artist_id=${encodeURIComponent(artistId ?? '')}`),
