// ─── Test 24: EmptyDashboardState — 3 CTAs render for new users ──────────────

test('EmptyDashboardState renders with 3 CTAs when user has no bookings', async ({ signedInPage: page }) => {
  await gotoDashboard(page)

  const emptyState = page.locator('[data-testid="empty-dashboard-state"]')

  // If the user has bookings, this state won't show — skip gracefully
  if (!(await emptyState.isVisible({ timeout: 5_000 }).catch(() => false))) {
    test.skip()
    return
  }

  await expect(emptyState).toBeVisible()

  // Must contain "Create appointment" CTA
  await expect(emptyState.locator('a, button', { hasText: /Create appointment/i }).first()).toBeVisible()

  // Must contain "Explore design" / design CTA
  await expect(emptyState.locator('a, button', { hasText: /Explore/i }).first()).toBeVisible()
})

// ─── Test 25: "See sample dashboard" sets demo mode and reloads ──────────────

test('"See sample dashboard" — clicking sets demo localStorage flag', async ({ signedInPage: page }) => {
  await gotoDashboard(page)

  const emptyState = page.locator('[data-testid="empty-dashboard-state"]')
  if (!(await emptyState.isVisible({ timeout: 5_000 }).catch(() => false))) {
    test.skip()
    return
  }

  // Look for the "Explore design" or sample dashboard button
  const sampleBtn = emptyState.locator('a, button', { hasText: /Explore|sample/i }).first()
  if (!(await sampleBtn.isVisible({ timeout: 3_000 }).catch(() => false))) {
    test.skip()
    return
  }

  await sampleBtn.click()

  // After click, demo mode should be set and the dashboard should reload/update
  // We verify via localStorage — allow a moment for navigation
  await page.waitForTimeout(500)

  const demoFlag = await page.evaluate(() =>
    localStorage.getItem('inkos:demo-mode'),
  )
  // If the button navigates elsewhere (e.g. /dev/design), just verify no crash
  const url = page.url()
  expect(url).not.toMatch(/500|error/i)

  // If still on dashboard, demo flag should be set
  if (url.includes('/dashboard')) {
    expect(demoFlag).toBe('1')
  }
})

// ─── Test 26: Mobile — dashboard renders at 375px ────────────────────────────

test('dashboard renders correctly at 375px mobile viewport', async ({ signedInPage: page }) => {
  await page.setViewportSize({ width: 375, height: 812 })
  await gotoDashboard(page)

  // Main content must be visible
  const mainContent = page.locator('#main-content, main, [role="main"]').first()
  await expect(mainContent).toBeVisible()

  // No horizontal overflow — check scrollWidth vs clientWidth
  const overflow = await page.evaluate(() => {
    return document.documentElement.scrollWidth > document.documentElement.clientWidth
  })
  expect(overflow).toBe(false)
})

